components.onTick:
const g = state.fn === 'bowl' ? 2 * state.x : 0.6 * state.x + 4 * Math.cos(2 * state.x);
const nx = state.x - state.lr * g;
if (Math.abs(nx - state.x) < 1e-4 || Math.abs(nx) > 20) return null;
return { x: nx, path: [...state.path, nx].slice(-60) };

components.onClick:
const g = state.fn === 'bowl' ? 2 * state.x : 0.6 * state.x + 4 * Math.cos(2 * state.x);
const nx = clamp(state.x - state.lr * g, -20, 20);
return { x: nx, path: [...state.path, nx].slice(-60) };

components.draw:
const f = (x) => state.fn === 'bowl' ? x * x : 0.3 * x * x + 2 * Math.sin(2 * x);
const trail = state.path.map((x) => [x, f(x)]);
return [
  line(linspace(-5, 5, 160).map((x) => [x, f(x)]), { color: 'gray' }),
  line(trail, { color: 'orange', dashed: true }),
  points(trail, { color: 'orange', r: 3 }),
  point(state.x, f(state.x), { id: 'ball', draggable: true, color: 'blue' })
];
